import hashlib
import re
import unicodedata
from datetime import date
from calendar import monthrange

MONTHS = (
    "январ феврал март апрел ма июн июл август сентябр октябр ноябр декабр"
).split()
MONTH = r"(?:" + "|".join(MONTHS) + r")[а-яё]*"
RUS_DATE = rf"\b(\d{{1,2}})\s+({MONTH})\s+(\d{{4}})(?!\d)"
NUM_DATE = r"\b(\d{1,2})[./](\d{1,2})[./](\d{4})(?!\d)"
ISO_DATE = r"\b(\d{4})-(\d{2})-(\d{2})(?!\d)"
DATE_PATTERN = re.compile(f"{ISO_DATE}|{NUM_DATE}|{RUS_DATE}", re.I)
DOC_NUM = r"[A-ZА-ЯЁ]{1,12}\s*-\s*\d+(?:\s*[/–—-]\s*\d{4})?|\d+\s*[-–—]?\s*[Фф][Зз]"
ARTICLE_HEADING = re.compile(r"^Статья\s+(\d+(?:\.\d+)*)\.\s+(.+)", re.I)


def normalize(value: str) -> str:
    value = unicodedata.normalize("NFKC", value).casefold().replace("ё", "е")
    value = re.sub(r"[‐‑‒–—−]", "-", value)
    return " ".join(value.split())


def canonical_number(value: str) -> str:
    value = normalize(value).replace(" ", "")
    value = re.sub(r"(?<=\d)-(?=\d{4}$)", "/", value)
    value = re.sub(r"^(\d+)фз$", r"\1-фз", value)
    # Latinate spellings commonly used for Cyrillic contract prefixes.
    head, separator, tail = value.partition("-")
    return {"a": "а", "p": "п", "pt": "пт", "k": "к"}.get(head, head) + separator + tail


def stable_id(prefix: str, value: str) -> str:
    return prefix + hashlib.sha256(value.encode("utf-8")).hexdigest()[:20]


def dates_in(text: str) -> list[tuple[int, date]]:
    found = []
    for match in DATE_PATTERN.finditer(text):
        iso_year, iso_month, iso_day, day, month, year, rus_day, rus_month, rus_year = match.groups()
        try:
            if iso_year:
                result = date(int(iso_year), int(iso_month), int(iso_day))
            elif year:
                result = date(int(year), int(month), int(day))
            else:
                number = next(i for i, stem in enumerate(MONTHS, 1) if rus_month.lower().startswith(stem))
                result = date(int(rus_year), number, int(rus_day))
        except ValueError:
            continue
        found.append((match.start(), result))
    return found


def first_date(text: str) -> str | None:
    found = dates_in(text)
    return found[0][1].isoformat() if found else None


def query_period(text: str) -> tuple[str, str] | None:
    full = [when for _, when in dates_in(text)]
    if full:
        return min(full).isoformat(), max(full).isoformat()
    for match in re.finditer(rf"\b({MONTH})\s+(19\d{{2}}|20\d{{2}})\b", text, re.I):
        word, year = match.groups()
        month = next(i for i, stem in enumerate(MONTHS, 1) if word.lower().startswith(stem))
        return date(int(year), month, 1).isoformat(), date(
            int(year), month, monthrange(int(year), month)[1]
        ).isoformat()
    years = re.findall(r"\b(?:в|за|на|до|после|с)\s+(19\d{2}|20\d{2})(?:\s*г(?:од[ауе]?)?\.?\b|\b)|\b(19\d{2}|20\d{2})\s*год[ауе]?\b", text, re.I)
    if years:
        bounds = [first or second for first, second in years]
        return min(bounds) + "-01-01", max(bounds) + "-12-31"
    return None


def extract_metadata(path: str, text: str, sha256: str) -> dict:
    name = path.rsplit("/", 1)[-1]
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    header = lines[:8]
    title = header[0]
    kind, number, doc_date, edition, start, end = "other", None, None, None, None, None
    parent_number, article, law_code, export, source_url, subject = (None,) * 6
    counterparties = []
    if title.startswith("Источник:") or name.startswith("законы__"):
        kind = "law"
        source_url = next((line[4:].strip() for line in header if line.startswith("URL:")), None)
        export = next((first_date(line) for line in header if line.startswith("Дата выгрузки:")), None)
        heading = next((ARTICLE_HEADING.match(line) for line in lines if ARTICLE_HEADING.match(line)), None)
        code = re.match(r"законы__(.*?)_ст(\d+(?:\.\d+)*)_", name, re.I)
        if code:
            law_code, article = code.groups()
            title_code = {
                "ТК": "ТК РФ", "НК": "НК РФ", "КоАП": "КоАП РФ",
                "152ФЗ": "Федеральный закон № 152-ФЗ", "МРОТ": "Федеральный закон о МРОТ",
            }.get(law_code, law_code)
            title = f"{title_code}, ст. {article}"
        if heading:
            article = heading[1]
            subject = heading[2] or None
        if re.fullmatch(r"\d+ФЗ", law_code or "", re.I):
            number = law_code[:-2] + "-ФЗ"
        elif law_code in {"МРОТ", "ТК"}:
            explicit_number = re.search(r"(?:N|№)\s*(\d+-ФЗ)", header[0], re.I)
            number = explicit_number[1] if explicit_number else None
        if re.search(r"(?:Трудовой|Налоговый) кодекс|Федеральный закон от", header[0], re.I):
            doc_date = first_date(header[0])
        prefix = lines[:next((i for i, line in enumerate(lines) if ARTICLE_HEADING.match(line)), len(header))]
        effective_dates = [
            found for line in prefix
            if article and re.match(rf"Статья\s+{re.escape(article)}\s+изменена\s+с\b", line, re.I)
            if (found := first_date(line)) and export and found <= export
        ]
        start = max(effective_dates, default=None)
    else:
        title = next((line for line in header if re.match(
            r"^(?:ДОГОВОР|ДОПОЛНИТЕЛЬНОЕ СОГЛАШЕНИЕ|РЕГЛАМЕНТ|СЛУЖЕБНАЯ ЗАПИСКА)\b", line
        )), title)
        if title.startswith("ДОГОВОР"):
            kind, doc_date = "contract", first_date(header[1]) if len(header) > 1 else None
            term = next((line for line in lines if re.search(r"Договор вступает в силу с даты подписания", line, re.I)), "")
            if term:
                start = doc_date
                if match := re.search(r"действует до\s+(.+)", term, re.I):
                    end_date = first_date(match[1])
                    if end_date:
                        end = date.fromordinal(date.fromisoformat(end_date).toordinal() + 1).isoformat()
        elif title.startswith("ДОПОЛНИТЕЛЬНОЕ"):
            kind = "addendum"
            parent = re.search(rf"к договору[^\n]*?№\s*({DOC_NUM})", "\n".join(header), re.I)
            parent_number = parent[1] if parent else None
            doc_date = first_date(header[2]) if len(header) > 2 else None
            if re.search(r"вступает в силу с даты подписания", text, re.I):
                start = doc_date
            if parent_number:
                title += f" к договору № {parent_number}"
        elif title.startswith("РЕГЛАМЕНТ"):
            kind = "regulation"
            approved = next((line for line in header if line.lower().startswith(("утверждён", "утвержден"))), "")
            doc_date = first_date(approved)
            version = next((line for line in header if line.lower().startswith("редакция от")), "")
            edition = first_date(version)
            active = re.search(r"Действует с\s+(.+)", version, re.I)
            start = first_date(active[1]) if active else None
            end = next((first_date(line) for line in header if re.match(r"РЕДАКЦИЯ УТРАТИЛА СИЛУ с", line, re.I)), None)
        elif title.startswith("СЛУЖЕБНАЯ"):
            kind, doc_date = "memo", first_date(title)
            subject = next((line for line in header if line.startswith("О ")), None)
        elif any(line.startswith("Исх.") for line in header):
            kind = "letter"
            registration = next(line for line in header if line.startswith("Исх."))
            doc_date = first_date(registration)
            title = "Письмо службы комплаенс " + re.sub(r"^Исх\.\s*", "", registration)
            subject = next((line for line in header if line.startswith("О ")), None)
            start = next((first_date(line) for line in lines if re.match(rf"С {RUS_DATE}", line, re.I)), None)
        found_number = re.search(rf"№\s*({DOC_NUM}|\d+)", title, re.I)
        number = found_number[1] if found_number else None
        if kind in {"contract", "addendum"}:
            counterparties = list(dict.fromkeys(re.findall(r'ООО\s+[«"]([^»"]+)[»"]', "\n".join(header), re.I)))

    if kind in {"contract", "addendum"} and doc_date:
        title += f" от {date.fromisoformat(doc_date):%d.%m.%Y}"
    if edition:
        title += f" (ред. от {date.fromisoformat(edition):%d.%m.%Y})"
    return {
        "doc_id": stable_id("doc_", path), "file_name": name, "file_path": path,
        "sha256": sha256, "doc_title": title, "doc_type": kind, "doc_number": number,
        "doc_date": doc_date, "edition_date": edition, "effective_date": start,
        "validity_period": {"from": start, "to_exclusive": end} if start or end else None,
        "edition_group": normalize(title.split(" (ред.")[0]) if kind == "regulation" else None,
        "version_status": "current_snapshot" if kind == "law" and "действующая" in name else (
            "superseded" if kind == "regulation" and end else "current" if kind == "regulation" and start else None
        ),
        "parent_doc_id": None, "parent_doc_number": parent_number, "related_doc_ids": [],
        "counterparties": counterparties, "article": article, "law_code": law_code,
        "snapshot_date": export, "source_url": source_url, "subject": subject,
    }


def link_documents(documents: list) -> None:
    contracts = {}
    for doc in documents:
        meta = doc.metadata
        if meta["doc_type"] == "contract" and meta["doc_number"]:
            contracts.setdefault(canonical_number(meta["doc_number"]), []).append(meta)
    for doc in documents:
        meta = doc.metadata
        parent = meta["parent_doc_number"]
        matches = contracts.get(canonical_number(parent), []) if parent else []
        if len(matches) == 1:
            meta["parent_doc_id"] = matches[0]["doc_id"]
            matches[0]["related_doc_ids"].append(meta["doc_id"])


# --- retrieval/document_parser.py ---
import hashlib
from pathlib import Path, PurePosixPath
from zipfile import ZipFile



def load_documents(source: str | Path) -> tuple[list[ParsedDocument], list[dict]]:
    """Read a KB directory or its ZIP without extracting archive members."""
    source = Path(source)
    if not source.exists():
        raise FileNotFoundError(f"Knowledge base not found: {source}")
    documents, issues, paths = [], [], set()

    def read_one(relative: str, raw: bytes) -> None:
        path = PurePosixPath(relative.replace("\\", "/"))
        if path.is_absolute() or ".." in path.parts or ":" in path.parts[0]:
            raise ValueError("Unsafe path in knowledge base ZIP")
        parts = path.parts[1:] if path.parts[0].casefold() == "knowledge-base" else path.parts
        key = "/".join(("knowledge-base", *parts))
        if key in paths:
            raise ValueError(f"Duplicate knowledge base member: {key}")
        paths.add(key)
        if path.suffix.lower() not in {".txt", ".md"}:
            issues.append({"file_path": key, "issue": "unsupported_format"})
            return
        try:
            content = raw.decode("utf-8-sig")
        except UnicodeDecodeError:
            issues.append({"file_path": key, "issue": "invalid_utf8"})
            return
        if not content.strip() or "\x00" in content:
            issues.append({"file_path": key, "issue": "empty_or_binary"})
            return
        meta = extract_metadata(key, content, hashlib.sha256(raw).hexdigest())
        documents.append(ParsedDocument(meta, content))

    if source.is_dir():
        for path in sorted(source.rglob("*")):
            if path.is_file() and not path.is_symlink() and not path.name.startswith("."):
                read_one(path.relative_to(source).as_posix(), path.read_bytes())
    else:
        with ZipFile(source) as archive:
            for item in sorted(archive.infolist(), key=lambda entry: entry.filename):
                if not item.is_dir() and not any(
                    part.startswith(".") or part == "__MACOSX" for part in PurePosixPath(item.filename).parts
                ):
                    read_one(item.filename, archive.read(item))

    if not documents:
        raise ValueError(f"No readable UTF-8 TXT/MD documents in {source}")
    documents.sort(key=lambda doc: doc.metadata["file_path"])
    link_documents(documents)
    return documents, issues


# --- retrieval/chunker.py ---
import re


SECTION = re.compile(r"^(\d+)\.\s+(.+)")
CLAUSE = re.compile(r"^[«\"“]?(\d+(?:\.\d+)+(?:-\d+)?)\.?\s+")
ENUM = re.compile(r"^(?:\(([а-яa-z]|\d+(?:\.\d+)*(?:-\d+)?)\)|([а-яa-z]|\d+(?:\.\d+)*(?:-\d+)?)\))\s+", re.I)
APPENDIX = re.compile(r"^Приложение\s*(?:№\s*)?(\d+)?(?:[.\s]|$)", re.I)
NOTE = re.compile(
    r"^(?:ГАРАНТ:|См\.\s|Информация об изменениях:|"
    r"(?:Пункт|Подпункт|Часть|Абзац|Статья)\s+[\d.-]+\s+(?:измен[её]н|дополнен|введ[её]н|изложен|в редакции)|"
    r"Федеральн\w+ законами? от |О проверке конституционности |Положения статьи .+ применяются )",
    re.I,
)
DIRECTIVE = re.compile(
    r"^\s*(?:внимание\s+для\s+(?:ии|ai)|(?:системный промпт|system prompt)\s*:)"
    r"|(?:игнорируй(?:те)?|ignore)\s+(?:все\s+)?(?:остальные|предыдущие|prior|previous)"
    r"|не упоминай(?:те)? эту инструкцию",
    re.I,
)


def _windows(text: str, start: int, end: int):
    while end - start > MAX_CHARS:
        lower = start + MAX_CHARS * 2 // 3
        limit = start + MAX_CHARS
        boundary = max(text.rfind("\n", lower, limit), text.rfind(". ", lower, limit) + 1)
        if boundary <= lower:
            boundary = text.rfind(" ", lower, limit)
        if boundary <= lower:
            boundary = limit
        yield start, boundary
        overlap_start = boundary - OVERLAP
        space = text.find(" ", overlap_start, boundary)
        start = space + 1 if space >= 0 else overlap_start
    if end > start:
        yield start, end


def chunk_document(doc: ParsedDocument) -> tuple[list[Chunk], list[dict]]:
    text, base = doc.text, doc.metadata
    kind = base["doc_type"]
    section = clause = subclause = part = appendix = None
    amendment_target = pending_note = clause_effective = None
    clause_parent = None
    article = base["article"]
    chunks, issues = [], []
    span = None
    in_article = kind != "law"
    in_body = kind not in {"memo", "letter", "addendum"}
    law_parts = base["law_code"] in {"152ФЗ", "КоАП"}

    def flush() -> None:
        nonlocal span
        if span is None:
            return
        start, end = span
        span = None
        reference = [base["doc_title"]]
        if article and f"ст. {article}" not in base["doc_title"]:
            reference.append(f"ст. {article}")
        if appendix:
            reference.append(appendix)
        if part:
            reference.append(f"ч. {part}")
        if section and not (clause or part):
            reference.append(f"раздел {section}")
        if clause:
            reference.append(f"п. {clause}")
        if subclause:
            reference.append(f"подп. {subclause}")
        if amendment_target:
            reference.append(f"изменение п. {amendment_target} основного договора")
        source = ", ".join(reference)
        context = [source]
        if section and (clause or part):
            context.append(section)
        if base["subject"]:
            context.append(base["subject"])
        if base["counterparties"]:
            context.append("Стороны: " + "; ".join(base["counterparties"]))
        for left, right in _windows(text, start, end):
            raw = text[left:right]
            application = re.search(r"\b(?:применяется|применяются)\b[^\n]*?\b(после|начиная с)\s+(.+)", raw, re.I)
            meta = {
                **base, "section": section, "article": article, "part": part,
                "clause": clause, "subclause": subclause, "appendix": appendix,
                "amends_clause": amendment_target, "provision_effective_date": clause_effective,
                "amendment_application_date": first_date(application[2]) if amendment_target and application else None,
                "amendment_application_relation": application[1].lower() if amendment_target and application else None,
                "page_start": None, "page_end": None, "char_start": left, "char_end": right,
                "is_table": any(line.count("|") >= 2 for line in raw.splitlines()),
                "is_footnote": bool(re.match(r"^(?:\*+\)|Примечание\b)", raw)),
                "structure_path": [
                    {"level": level, "label": label}
                    for level, label in (("appendix", appendix), ("section", section),
                                         ("article", article), ("part", part),
                                         ("clause", clause), ("subclause", subclause)) if label
                ],
            }
            contextual = "\n".join((*context, raw))
            chunks.append(Chunk(
                stable_id("chunk_", f'{base["doc_id"]}:{left}:{right}'), base["doc_id"],
                raw, contextual, source, normalize(contextual), meta,
            ))

    offset = 0
    for line in text.splitlines(keepends=True):
        stripped = line.strip()
        left, right = offset + len(line) - len(line.lstrip()), offset + len(line.rstrip())
        offset += len(line)
        if not stripped:
            if kind == "law":
                flush()
            continue
        if DIRECTIVE.search(stripped):
            flush()
            issues.append({"file_path": base["file_path"], "issue": "quarantined_prompt_directive",
                           "char_start": left, "char_end": right})
            continue
        if kind == "law":
            heading = ARTICLE_HEADING.match(stripped)
            if heading and not NOTE.match(stripped):
                flush()
                article, in_article = heading[1], True
                clause = subclause = part = pending_note = clause_effective = None
                if base["law_code"] == "МРОТ":
                    span = (left, right)
                continue
            if not in_article:
                continue
            if NOTE.match(stripped):
                flush()
                target = re.match(r"^(Пункт|Подпункт|Часть)\s+(\d+(?:\.\d+)*(?:-\d+)?)\s", stripped, re.I)
                if not target:
                    target = re.match(r"^Статья\s+[\d.]+\s+дополнена\s+(пунктом|частью)\s+([\d.-]+)\s", stripped, re.I)
                effective = first_date(stripped)
                if target and effective and (not base["snapshot_date"] or effective <= base["snapshot_date"]):
                    pending_note = (target[1].lower(), target[2], effective)
                continue
        else:
            if kind in {"memo", "letter"} and stripped == base["subject"]:
                in_body = True
                continue
            if kind == "addendum" and stripped.lower().startswith("изложить пункт"):
                in_body = True
            if not in_body:
                continue
            if re.match(r"^(?:Уважаемые коллеги!|Руководитель службы комплаенс|Начальник юридического отдела\s+\S\.)", stripped):
                continue
            if kind == "addendum" and re.match(r"^(?:Поставщик|Покупатель):", stripped):
                flush()
                continue
            attachment = APPENDIX.match(stripped)
            if attachment:
                flush()
                appendix = "Приложение" + (f" {attachment[1]}" if attachment[1] else "")
                section = clause = subclause = None
            if kind == "addendum" and (target := re.match(r"^Изложить пункт\s+(\d+(?:\.\d+)*)", stripped, re.I)):
                flush()
                amendment_target = target[1]
            if kind in {"regulation", "contract"} and (heading := SECTION.match(stripped)):
                flush()
                section, clause, subclause = stripped, None, None
                continue
            if kind in {"regulation", "contract"} and section is None and appendix is None:
                continue

        number = CLAUSE.match(stripped)
        numbered = SECTION.match(stripped)
        enumerated = ENUM.match(stripped)
        if (number or (numbered and kind == "law")) and not (
            kind == "addendum" and number and number[1] == amendment_target
        ):
            flush()
            label = number[1] if number else numbered[1]
            if kind != "addendum":
                if law_parts:
                    part, clause = label, None
                elif kind == "contract" and label.count(".") > 1:
                    clause, subclause = label.rsplit(".", 1)[0], label
                else:
                    clause = label
            if not (kind == "contract" and label.count(".") > 1):
                subclause = None
            clause_parent = None
            clause_effective = None
            if pending_note and pending_note[1] == label and pending_note[0] != "подпункт":
                clause_effective = pending_note[2]
                pending_note = None
        elif enumerated:
            flush()
            if subclause is None:
                clause_parent = clause_effective
            subclause = enumerated[1] or enumerated[2]
            clause_effective = clause_parent
            if pending_note and pending_note[:2] == ("подпункт", subclause):
                clause_effective = max(clause_effective or "", pending_note[2])
                pending_note = None
        elif kind in {"memo", "letter"}:
            flush()
        if span is None:
            span = (left, right)
        else:
            span = (span[0], right)
    flush()
    if not chunks:
        issues.append({"file_path": base["file_path"], "issue": "no_searchable_provisions"})
    return chunks, issues


